import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { entregadoresAPI } from '../services/api';
import { Trash2, Edit2 } from 'lucide-react';

const EntregadorList: React.FC = () => {
  const [entregadores, setEntregadores] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchEntregadores = async () => {
      try {
        setLoading(true);
        const response = await entregadoresAPI.listar();
        setEntregadores(response.data);
      } catch (err) {
        setError('Erro ao carregar entregadores');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchEntregadores();
  }, []);

  const handleDelete = async (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir este entregador?')) {
      try {
        await entregadoresAPI.deletar(id);
        setEntregadores(entregadores.filter(entregador => entregador.idEntrg !== id));
      } catch (err) {
        setError('Erro ao excluir entregador');
        console.error(err);
      }
    }
  };

  if (loading) return <div className="text-center py-10">Carregando...</div>;
  if (error) return <div className="text-center text-red-500 py-10">{error}</div>;

  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-800">Entregadores</h1>
        <Link to="/entregadores/novo" className="bg-indigo-600 text-white px-4 py-2 rounded-md hover:bg-indigo-700 transition-colors">
          Novo Entregador
        </Link>
      </div>

      {entregadores.length === 0 ? (
        <div className="text-center py-10 text-gray-500">
          Nenhum entregador cadastrado.
        </div>
      ) : (
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Nome</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">CNH</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Placa Veículo</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Tipo Veículo</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Telefone</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Ações</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {entregadores.map((entregador) => (
                <tr key={entregador.idEntrg} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">{entregador.nomEntrg}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{entregador.numCNHEntrg}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{entregador.dscPlacaVeiculoEntrg}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{entregador.dscTipoVeiculoEntrg}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{entregador.numTelefoneEntrg}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500 flex space-x-2">
                    <Link to={`/entregadores/${entregador.idEntrg}/editar`} className="text-indigo-600 hover:text-indigo-900">
                      <Edit2 className="h-4 w-4" />
                    </Link>
                    <button onClick={() => handleDelete(entregador.idEntrg)} className="text-red-600 hover:text-red-900">
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default EntregadorList;
